/*
【算法說明】
本題要求用最少的直線次數覆蓋至少 m 個點。給定 n 個點的座標 (n <= 16)。
由於點的數量很少，可以使用狀態壓縮動態規劃 (State Compression DP)。

算法步驟：
1. 預處理所有可能的直線：遍歷任意兩點 (i, j)，找到所有落在此直線上的點集，用一個位掩碼 (mask) 表示。
   特別地，如果只有一個點，也可以由一條直線覆蓋。
2. 定義 `dp[mask]` 為覆蓋位掩碼 `mask` 代表的點集所需的最少直線數。
   初始化 `dp[0] = 0`，其餘為正無窮。
3. 狀態轉移：對於每個狀態 `mask`，嘗試添加一條預處理好的直線 `line_mask`：
   `dp[mask | line_mask] = min(dp[mask | line_mask], dp[mask] + 1)`。
4. 最後，遍歷所有 `mask`，如果 `popcount(mask) >= m`，則取 `dp[mask]` 的最小值。
*/

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Point {
    int x, y;
};

int countSetBits(int n) {
    int count = 0;
    while (n > 0) {
        n &= (n - 1);
        count++;
    }
    return count;
}

bool isCollinear(Point p1, Point p2, Point p3) {
    return (p2.y - p1.y) * (p3.x - p2.x) == (p3.y - p2.y) * (p2.x - p1.x);
}

void solve(int t) {
    int n, m;
    if (!(cin >> n >> m)) return;
    vector<Point> points(n);
    for (int i = 0; i < n; ++i) cin >> points[i].x >> points[i].y;

    vector<int> lines;
    for (int i = 0; i < n; ++i) {
        lines.push_back(1 << i);
        for (int j = i + 1; j < n; ++j) {
            int mask = (1 << i) | (1 << j);
            for (int k = j + 1; k < n; ++k) {
                if (isCollinear(points[i], points[j], points[k])) {
                    mask |= (1 << k);
                }
            }
            lines.push_back(mask);
        }
    }
    sort(lines.begin(), lines.end());
    lines.erase(unique(lines.begin(), lines.end()), lines.end());

    vector<int> dp(1 << n, n + 1);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (dp[mask] > n) continue;
        for (int line : lines) {
            int next_mask = mask | line;
            if (dp[next_mask] > dp[mask] + 1) {
                dp[next_mask] = dp[mask] + 1;
            }
        }
    }

    int min_shots = n;
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (countSetBits(mask) >= m) {
            min_shots = min(min_shots, dp[mask]);
        }
    }

    cout << "Case #" << t << ":" << endl;
    cout << min_shots << endl;
}

int main() {
    int T;
    if (!(cin >> T)) return 0;
    for (int i = 1; i <= T; ++i) {
        solve(i);
        if (i < T) cout << endl;
    }
    return 0;
}
